API Gateway & Routing.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(api_gateway_routing, "API Gateway & Routing") {
    Component(Ingress_WAF_Controller, "Ingress WAF Controller", "Kong Enterprise Plugin", "Manages ingress traffic, Web Application Firewall protection, and threat mitigation.")
    Component(Geo_Routing_DNS_Router, "Geo-Routing & DNS Router", "Kong Enterprise / GCP Cloud DNS", "Routes client requests to the appropriate regional data residency boundary (EU vs US).")
    Component(mTLS_Security_Terminator, "mTLS & Security Terminator", "Kong Enterprise mTLS Plugin", "Terminates incoming TLS connections and establishes secure mTLS sessions for internal routing.")
}

Rel(Ingress_WAF_Controller, Geo_Routing_DNS_Router, "Filters and passes validated ingress requests", "")
Rel(Geo_Routing_DNS_Router, mTLS_Security_Terminator, "Forwards geographically routed requests for secure internal dispatch", "")

@enduml

FHIR & E-Prescription Integration Servic.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(fhirdatasvc, "FHIR & E-Prescription Integration Service") {
    Component(FHIR_Transformer, "FHIR Transformer", "Python / Java (HAPI FHIR)", "Transforms internal data models into US Core profiles and national eHDSI/OpenNCP standards.")
    Component(EPrescription_Router, "E-Prescription Router", "Python / Java", "Routes e-prescriptions to National E-Prescription Gateways in the EU and US Pharmacy Networks.")
}

Rel(FHIR_Transformer, EPrescription_Router, "Passes standardized FHIR payloads", "Internal")

@enduml

Databases.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Component(Consent_Audit_Logging_Service, "Consent & Audit Logging Service", "Go", "External service interacting with databases")

Container_Boundary(Databases, "Databases") {
    Component(Cloud_SQL_PostgreSQL, "Cloud SQL PostgreSQL", "Google Cloud SQL / PostgreSQL with Row-Level Security", "Regional transactional databases managing patient data and consent enforcement.")
    Component(Cloud_Storage, "Cloud Storage", "Google Cloud Storage WORM Buckets", "Regional storage with CMEK for immutable AI traceability logging.")
    Component(Regional_Memorystore_for_Redis, "Regional Memorystore for Redis", "Google Cloud Memorystore", "Provides fast patient-to-region mapping caches.")
}

Rel(Consent_Audit_Logging_Service, Cloud_SQL_PostgreSQL, "Stores audit logs and consent records encrypted via CMEK", "HTTPS / Internal")
Rel(Consent_Audit_Logging_Service, Cloud_Storage, "Stores immutable audit and traceability logs encrypted via CMEK", "HTTPS / Internal")

@enduml
